import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String s = br.readLine().trim();
        int n = s.length(), count = 0;
        boolean[] placed = new boolean[n];
        for (int i = 0; i < n;) {
            // skip seats that are not girls or girls already covered from the left
            if (s.charAt(i) != 'G' || (i > 0 && placed[i - 1])) { i++; continue; }
            if (i + 1 < n && s.charAt(i + 1) == '-') { placed[i + 1] = true; count++; i += 2; } // prefer the right seat
            else if (i > 0 && s.charAt(i - 1) == '-') { placed[i - 1] = true; count++; i++; }
            else { System.out.println(-1); return; }
        }
        System.out.println(count);
    }
}

